/* Türkisch A1 – Wortschatz für Deutschsprechende (Übersetzungen und Hinweise auf Deutsch)
 * Feste IDs (tr-a1.w001 …): nie ändern, nie wiederverwenden. Neue Wörter → neue ID am Ende.
 * Alle Beispielsätze sind selbst geschrieben.
 */
(function (K) {
K.addVocab('tr-a1', [
  /* ---------- Begrüßung & Höflichkeit (greet) ---------- */
  { id: "tr-a1.w001", t: "merhaba", pos: "phr", n: "Hallo; Guten Tag", ex: "Merhaba, ben Deniz.", exn: "Hallo, ich bin Deniz.", topic: "greet" },
  { id: "tr-a1.w002", t: "selam", pos: "phr", n: "Hi; Hallo (locker)", ex: "Selam, naber?", exn: "Hi, was geht?", topic: "greet", note: "Nur unter Freunden und Gleichaltrigen. „Naber?“ ist die Kurzform von „Ne haber?“ (Was gibt’s Neues?)." },
  { id: "tr-a1.w003", t: "günaydın", pos: "phr", n: "Guten Morgen", ex: "Günaydın anne, kahvaltı hazır mı?", exn: "Guten Morgen, Mama, ist das Frühstück fertig?", topic: "greet", note: "Nur morgens, etwa bis 11 Uhr. Danach: „İyi günler“ oder „Merhaba“." },
  { id: "tr-a1.w004", t: "iyi akşamlar", pos: "phr", n: "Guten Abend; Schönen Abend", ex: "İyi akşamlar, hoş geldiniz!", exn: "Guten Abend, willkommen!", topic: "greet" },
  { id: "tr-a1.w005", t: "iyi geceler", pos: "phr", n: "Gute Nacht", ex: "Çok yoruldum, iyi geceler.", exn: "Ich bin sehr müde, gute Nacht.", topic: "greet" },
  { id: "tr-a1.w006", t: "hoşça kal", pos: "phr", n: "Tschüss; Mach’s gut (sagt, wer geht)", ex: "Ben gidiyorum, hoşça kal!", exn: "Ich gehe jetzt, mach’s gut!", topic: "greet", note: "Sagt die Person, die **geht**. Zu mehreren oder höflich: „Hoşça kalın“. Die Antwort ist „Güle güle“." },
  { id: "tr-a1.w007", t: "güle güle", pos: "phr", n: "Tschüss (sagt, wer bleibt)", ex: "Güle güle, yine bekleriz!", exn: "Tschüss, komm bald wieder!", topic: "greet", note: "Sagt die Person, die **bleibt** – nie der, der geht. Wörtlich: „lachend, lachend“." },
  { id: "tr-a1.w008", t: "görüşürüz", pos: "phr", n: "Bis bald; Wir sehen uns", ex: "Yarın görüşürüz!", exn: "Bis morgen!", topic: "greet" },
  { id: "tr-a1.w009", t: "teşekkür ederim", pos: "phr", n: "Danke", ex: "Yardımın için teşekkür ederim.", exn: "Danke für deine Hilfe.", topic: "greet", note: "Lockerer: „Teşekkürler“ oder „Sağ ol“." },
  { id: "tr-a1.w010", t: "sağ ol", pos: "phr", n: "Danke (locker)", ex: "Sağ ol, çok naziksin.", exn: "Danke, du bist sehr nett.", topic: "greet", note: "Wörtlich „Sei gesund“. Höflich oder zu mehreren: „Sağ olun“." },
  { id: "tr-a1.w011", t: "rica ederim", pos: "phr", n: "Gern geschehen; Bitte (als Antwort auf Danke)", ex: "Rica ederim, ne demek!", exn: "Gern geschehen, keine Ursache!", topic: "greet", note: "Das deutsche „bitte“ hat drei Entsprechungen: **lütfen** (wenn man um etwas bittet), **buyurun** (wenn man etwas anbietet oder reicht), **rica ederim** (als Antwort auf Danke)." },
  { id: "tr-a1.w012", t: "lütfen", pos: "phr", n: "bitte (bei einer Bitte)", ex: "Bir çay, lütfen.", exn: "Einen Tee, bitte.", topic: "greet" },
  { id: "tr-a1.w013", t: "buyurun", pos: "phr", n: "Bitte schön; Hier, bitte; Herein", ex: "Buyurun, içeri girin.", exn: "Bitte, kommen Sie herein.", topic: "greet", note: "Beim Anbieten, Überreichen, Hereinbitten – und wenn ein Kunde den Laden betritt („Was darf’s sein?“). Zu einer Person, die man duzt: „Buyur“." },
  { id: "tr-a1.w014", t: "özür dilerim", pos: "phr", n: "Entschuldigung; Es tut mir leid", ex: "Özür dilerim, geç kaldım.", exn: "Entschuldigung, ich bin zu spät.", topic: "greet" },
  { id: "tr-a1.w015", t: "affedersiniz", pos: "phr", n: "Entschuldigen Sie (zum Ansprechen)", ex: "Affedersiniz, saat kaç?", exn: "Entschuldigen Sie, wie spät ist es?", topic: "greet", note: "Um Fremde höflich anzusprechen. Für eine echte Entschuldigung eher „Özür dilerim“." },
  { id: "tr-a1.w016", t: "nasılsın", pos: "phr", n: "Wie geht es dir?", ex: "Uzun zamandır görüşmedik, nasılsın?", exn: "Wir haben uns lange nicht gesehen, wie geht’s dir?", topic: "greet", note: "Sie-Form: „Nasılsınız?“" },
  { id: "tr-a1.w017", t: "iyiyim", pos: "phr", n: "Mir geht es gut", ex: "İyiyim, teşekkürler. Sen nasılsın?", exn: "Mir geht’s gut, danke. Und dir?", topic: "greet", note: "iyi (gut) + -yim (ich bin): wörtlich „Ich bin gut“." },
  { id: "tr-a1.w018", t: "hoş geldin", pos: "phr", n: "Willkommen", ex: "Hoş geldin! Gel, otur.", exn: "Willkommen! Komm, setz dich.", topic: "greet", note: "Sie-Form: „Hoş geldiniz“. Die feste Antwort ist „Hoş bulduk“ (wörtlich: „Wir haben es angenehm vorgefunden“)." },
  { id: "tr-a1.w019", t: "memnun oldum", pos: "phr", n: "Freut mich (beim Kennenlernen)", ex: "Tanıştığımıza memnun oldum.", exn: "Freut mich, Sie kennenzulernen.", topic: "greet", note: "Antwort: „Ben de memnun oldum“ (Freut mich auch)." },
  { id: "tr-a1.w020", t: "afiyet olsun", pos: "phr", n: "Guten Appetit; Wohl bekomm’s", ex: "Yemek hazır, afiyet olsun!", exn: "Das Essen ist fertig, guten Appetit!", topic: "greet", note: "Sagt man vor dem Essen, aber auch danach, wenn sich jemand für das Essen bedankt." },

  /* ---------- Personen & Familie (people) ---------- */
  { id: "tr-a1.w021", t: "anne", pos: "n", n: "die Mutter", ex: "Annem öğretmen.", exn: "Meine Mutter ist Lehrerin.", topic: "people" },
  { id: "tr-a1.w022", t: "baba", pos: "n", n: "der Vater", ex: "Babam şu an evde değil.", exn: "Mein Vater ist gerade nicht zu Hause.", topic: "people" },
  { id: "tr-a1.w023", t: "kardeş", pos: "n", n: "das Geschwister; der Bruder / die Schwester", ex: "İki kardeşim var.", exn: "Ich habe zwei Geschwister.", topic: "people", note: "kardeş sagt nichts über das Geschlecht. Genauer: erkek kardeş (Bruder), kız kardeş (Schwester). Nach Zahlen kein Plural: iki kardeş (nicht „iki kardeşler“)." },
  { id: "tr-a1.w024", t: "abla", pos: "n", n: "die ältere Schwester", ex: "Ablam İzmir'de yaşıyor.", exn: "Meine ältere Schwester lebt in Izmir.", topic: "people", note: "Auch freundliche Anrede für etwas ältere, fremde Frauen – z. B. auf dem Markt." },
  { id: "tr-a1.w025", t: "ağabey", pos: "n", n: "der ältere Bruder", ex: "Ağabeyim mühendis.", exn: "Mein älterer Bruder ist Ingenieur.", topic: "people", note: "Gesprochen fast immer „abi“. Auch als Anrede für etwas ältere Männer üblich." },
  { id: "tr-a1.w026", t: "çocuk", pos: "n", n: "das Kind", ex: "Çocuklar bahçede oynuyor.", exn: "Die Kinder spielen im Garten.", topic: "people", note: "Vor Vokal wird k zu ğ: çocuğum (mein Kind), çocuğu." },
  { id: "tr-a1.w027", t: "oğul", pos: "n", n: "der Sohn", ex: "Oğlum on yaşında.", exn: "Mein Sohn ist zehn Jahre alt.", topic: "people", note: "Vor einer vokalischen Endung fällt das u weg: oğul → oğlum, oğlu." },
  { id: "tr-a1.w028", t: "kız", pos: "n", n: "das Mädchen; die Tochter", ex: "Kızım ilkokula gidiyor.", exn: "Meine Tochter geht in die Grundschule.", topic: "people" },
  { id: "tr-a1.w029", t: "adam", pos: "n", n: "der Mann", ex: "Kapıda bir adam var.", exn: "An der Tür steht ein Mann.", topic: "people", note: "„erkek“ heißt ebenfalls Mann, betont aber das Geschlecht (männlich, Junge)." },
  { id: "tr-a1.w030", t: "kadın", pos: "n", n: "die Frau", ex: "Bu kadın bizim komşumuz.", exn: "Diese Frau ist unsere Nachbarin.", topic: "people", note: "Die Ehefrau heißt nicht kadın, sondern eş oder karım (umgangssprachlich)." },
  { id: "tr-a1.w031", t: "eş", pos: "n", n: "der Ehepartner / die Ehepartnerin", ex: "Eşim Almanya'da çalışıyor.", exn: "Meine Frau arbeitet in Deutschland.", topic: "people", note: "eş ist geschlechtsneutral: eşim = mein Mann oder meine Frau. Die höfliche, neutrale Wahl." },
  { id: "tr-a1.w032", t: "aile", pos: "n", n: "die Familie", ex: "Ailem çok kalabalık.", exn: "Meine Familie ist sehr groß.", topic: "people", note: "kalabalık = mit vielen Menschen – bei Familien sagt man das statt „büyük“." },
  { id: "tr-a1.w033", t: "arkadaş", pos: "n", n: "der Freund / die Freundin", ex: "Bu benim arkadaşım Can.", exn: "Das ist mein Freund Can.", topic: "people", note: "Immer freundschaftlich gemeint. Für eine Liebesbeziehung sagt man „sevgili“." },
  { id: "tr-a1.w034", t: "dede", pos: "n", n: "der Opa; der Großvater", ex: "Dedem köyde yaşıyor.", exn: "Mein Opa lebt im Dorf.", topic: "people" },
  { id: "tr-a1.w035", t: "anneanne", pos: "n", n: "die Oma (Mutter der Mutter)", ex: "Anneannem çok güzel börek yapıyor.", exn: "Meine Oma macht sehr leckeren Börek.", topic: "people", note: "Die Mutter des Vaters heißt babaanne. Allgemein: büyükanne." },
  { id: "tr-a1.w036", t: "amca", pos: "n", n: "der Onkel (Bruder des Vaters)", ex: "Amcam bu akşam bize geliyor.", exn: "Mein Onkel kommt heute Abend zu uns.", topic: "people", note: "Der Bruder der Mutter heißt dayı. „Amca“ ist auch eine höfliche Anrede für ältere Männer." },
  { id: "tr-a1.w037", t: "teyze", pos: "n", n: "die Tante (Schwester der Mutter)", ex: "Teyzem Ankara'da oturuyor.", exn: "Meine Tante wohnt in Ankara.", topic: "people", note: "Die Schwester des Vaters heißt hala. „Teyze“ ist auch eine freundliche Anrede für ältere Frauen." },
  { id: "tr-a1.w038", t: "bebek", pos: "n", n: "das Baby", ex: "Bebek uyuyor, sessiz olun.", exn: "Das Baby schläft, seid leise.", topic: "people", note: "Vor Vokal wird k zu ğ: bebeğim (mein Baby)." },
  { id: "tr-a1.w039", t: "insan", pos: "n", n: "der Mensch", ex: "Burada çok insan var.", exn: "Hier sind viele Menschen.", topic: "people", note: "Nach „çok“ steht kein Plural: çok insan (nicht „çok insanlar“)." },
  { id: "tr-a1.w040", t: "komşu", pos: "n", n: "der Nachbar / die Nachbarin", ex: "Komşumuz çok iyi biri.", exn: "Unser Nachbar ist ein sehr netter Mensch.", topic: "people" },
  { id: "tr-a1.w041", t: "isim", pos: "n", n: "der Name", ex: "Senin ismin ne?", exn: "Wie heißt du?", topic: "people", note: "Vor Vokal fällt das zweite i weg: isim → ismim, ismin. Gleichbedeutend: ad (Adın ne?)." },
  { id: "tr-a1.w042", t: "yaş", pos: "n", n: "das Alter; das Lebensjahr", ex: "Kaç yaşındasın?", exn: "Wie alt bist du?", topic: "people", note: "Das Alter sagt man mit „yaşında“: On yaşındayım = Ich bin zehn Jahre alt." },
  { id: "tr-a1.w043", t: "evli", pos: "adj", n: "verheiratet", ex: "Ablam evli, iki çocuğu var.", exn: "Meine ältere Schwester ist verheiratet und hat zwei Kinder.", topic: "people", note: "ev (Haus) + -li: wörtlich „mit Haus(halt)“. Gegenteil: bekâr (ledig)." },
  { id: "tr-a1.w044", t: "misafir", pos: "n", n: "der Gast", ex: "Bu akşam misafirimiz var.", exn: "Heute Abend haben wir Gäste.", topic: "people" },
  { id: "tr-a1.w045", t: "kişi", pos: "n", n: "die Person", ex: "Kaç kişisiniz?", exn: "Wie viele Personen sind Sie?", topic: "people" },
  { id: "tr-a1.w046", t: "hanım", pos: "n", n: "Frau (Anrede, nach dem Vornamen)", ex: "Elif Hanım, buyurun.", exn: "Bitte schön, Frau Elif.", topic: "people", note: "Steht **nach dem Vornamen** und wird dann großgeschrieben: Elif Hanım – nicht wie im Deutschen vor dem Nachnamen." },
  { id: "tr-a1.w047", t: "bey", pos: "n", n: "Herr (Anrede, nach dem Vornamen)", ex: "Ahmet Bey burada mı?", exn: "Ist Herr Ahmet hier?", topic: "people", note: "Wie hanım: nach dem Vornamen und großgeschrieben: Ahmet Bey." },

  /* ---------- Zahlen, Zeit & Kalender (numbers) ---------- */
  { id: "tr-a1.w048", t: "bir", pos: "x", n: "eins; ein / eine", ex: "Bir kahve, lütfen.", exn: "Einen Kaffee, bitte.", topic: "numbers", note: "bir ist auch der unbestimmte Artikel „ein/eine“." },
  { id: "tr-a1.w049", t: "iki", pos: "x", n: "zwei", ex: "İki bilet istiyorum.", exn: "Ich möchte zwei Fahrkarten.", topic: "numbers", note: "Nach Zahlen steht kein Plural: iki bilet (nicht „iki biletler“)." },
  { id: "tr-a1.w050", t: "üç", pos: "x", n: "drei", ex: "Üç çocuğumuz var.", exn: "Wir haben drei Kinder.", topic: "numbers" },
  { id: "tr-a1.w051", t: "dört", pos: "x", n: "vier", ex: "Toplantı saat dörtte.", exn: "Die Besprechung ist um vier Uhr.", topic: "numbers", note: "Nach t wird das d der Endung zu t: dörtte (nicht „dörtde“)." },
  { id: "tr-a1.w052", t: "beş", pos: "x", n: "fünf", ex: "Beş dakika bekleyin, lütfen.", exn: "Warten Sie bitte fünf Minuten.", topic: "numbers" },
  { id: "tr-a1.w053", t: "altı", pos: "x", n: "sechs", ex: "Kızım altı yaşında.", exn: "Meine Tochter ist sechs Jahre alt.", topic: "numbers", note: "Mit ı ohne Punkt. „altı“ heißt auch „Unterseite“: masanın altı (unter dem Tisch)." },
  { id: "tr-a1.w054", t: "yedi", pos: "x", n: "sieben", ex: "Bir haftada yedi gün var.", exn: "Eine Woche hat sieben Tage.", topic: "numbers" },
  { id: "tr-a1.w055", t: "sekiz", pos: "x", n: "acht", ex: "Sabah sekizde kalkıyorum.", exn: "Ich stehe morgens um acht auf.", topic: "numbers" },
  { id: "tr-a1.w056", t: "dokuz", pos: "x", n: "neun", ex: "Market dokuzda açılıyor.", exn: "Der Supermarkt macht um neun auf.", topic: "numbers" },
  { id: "tr-a1.w057", t: "on", pos: "x", n: "zehn", ex: "Bu kitap on lira.", exn: "Dieses Buch kostet zehn Lira.", topic: "numbers", note: "Zusammengesetzte Zahlen einfach hintereinander: on bir (11), on iki (12), yirmi beş (25)." },
  { id: "tr-a1.w058", t: "yirmi", pos: "x", n: "zwanzig", ex: "Yirmi yaşındayım.", exn: "Ich bin zwanzig Jahre alt.", topic: "numbers" },
  { id: "tr-a1.w059", t: "otuz", pos: "x", n: "dreißig", ex: "Sınıfta otuz öğrenci var.", exn: "In der Klasse sind dreißig Schüler.", topic: "numbers" },
  { id: "tr-a1.w060", t: "kırk", pos: "x", n: "vierzig", ex: "Babam kırk beş yaşında.", exn: "Mein Vater ist fünfundvierzig.", topic: "numbers", note: "Mit ı ohne Punkt: kırk, nicht „kirk“. Die Einer kommen nach den Zehnern: kırk beş (45)." },
  { id: "tr-a1.w061", t: "elli", pos: "x", n: "fünfzig", ex: "Bilet elli lira.", exn: "Die Fahrkarte kostet fünfzig Lira.", topic: "numbers" },
  { id: "tr-a1.w062", t: "yüz", pos: "x", n: "hundert", ex: "Yüz metre ileride bir eczane var.", exn: "Hundert Meter weiter vorne ist eine Apotheke.", topic: "numbers", note: "Ohne „bir“: yüz = 100 (nicht „bir yüz“). yüz heißt auch „Gesicht“." },
  { id: "tr-a1.w063", t: "bin", pos: "x", n: "tausend", ex: "Bu bisiklet beş bin lira.", exn: "Dieses Fahrrad kostet fünftausend Lira.", topic: "numbers", note: "Ebenfalls ohne „bir“: bin = 1000. Achtung: bin! heißt auch „Steig ein!“ (von binmek)." },
  { id: "tr-a1.w064", t: "yarım", pos: "x", n: "halb", ex: "Yarım kilo peynir, lütfen.", exn: "Ein halbes Kilo Käse, bitte.", topic: "numbers", note: "yarım steht allein vor dem Nomen. Nach einer Zahl sagt man buçuk: iki buçuk (zweieinhalb), saat üç buçuk (halb vier)." },
  { id: "tr-a1.w065", t: "saat", pos: "n", n: "die Uhr; die Stunde", ex: "Saat kaç?", exn: "Wie spät ist es?", topic: "numbers", note: "Ausnahme der Vokalharmonie: Die Endungen sind hell – saatler, saati, saatte (nicht „saatlar“)." },
  { id: "tr-a1.w066", t: "dakika", pos: "n", n: "die Minute", ex: "Otobüs on dakika sonra geliyor.", exn: "Der Bus kommt in zehn Minuten.", topic: "numbers" },
  { id: "tr-a1.w067", t: "gün", pos: "n", n: "der Tag", ex: "Günde sekiz saat çalışıyorum.", exn: "Ich arbeite acht Stunden am Tag.", topic: "numbers" },
  { id: "tr-a1.w068", t: "hafta", pos: "n", n: "die Woche", ex: "Gelecek hafta tatildeyim.", exn: "Nächste Woche bin ich im Urlaub.", topic: "numbers" },
  { id: "tr-a1.w069", t: "ay", pos: "n", n: "der Monat; der Mond", ex: "Bir ay İstanbul'da kalıyorum.", exn: "Ich bleibe einen Monat in Istanbul.", topic: "numbers" },
  { id: "tr-a1.w070", t: "yıl", pos: "n", n: "das Jahr", ex: "Her yıl Türkiye'ye gidiyoruz.", exn: "Jedes Jahr fahren wir in die Türkei.", topic: "numbers", note: "Gleichbedeutend: sene. Mit ı ohne Punkt." },
  { id: "tr-a1.w071", t: "bugün", pos: "adv", n: "heute", ex: "Bugün çok sıcak.", exn: "Heute ist es sehr heiß.", topic: "numbers", note: "Zusammengeschrieben: bu + gün = bugün." },
  { id: "tr-a1.w072", t: "yarın", pos: "adv", n: "morgen", ex: "Yarın sabah erken kalkıyorum.", exn: "Morgen früh stehe ich früh auf.", topic: "numbers" },
  { id: "tr-a1.w073", t: "dün", pos: "adv", n: "gestern", ex: "Dün çok yağmur yağdı.", exn: "Gestern hat es viel geregnet.", topic: "numbers" },
  { id: "tr-a1.w074", t: "sabah", pos: "n", n: "der Morgen; morgens", ex: "Her sabah kahvaltı yapıyorum.", exn: "Ich frühstücke jeden Morgen.", topic: "numbers" },
  { id: "tr-a1.w075", t: "akşam", pos: "n", n: "der Abend; abends", ex: "Akşam arkadaşlarla buluşuyorum.", exn: "Heute Abend treffe ich mich mit Freunden.", topic: "numbers" },
  { id: "tr-a1.w076", t: "gece", pos: "n", n: "die Nacht; nachts", ex: "Gece sokak çok sessiz.", exn: "Nachts ist die Straße sehr ruhig.", topic: "numbers" },
  { id: "tr-a1.w077", t: "pazartesi", pos: "n", n: "der Montag", ex: "Pazartesi kurs başlıyor.", exn: "Am Montag fängt der Kurs an.", topic: "numbers", note: "Wochentage schreibt man klein – außer in einem vollständigen Datum (18 Kasım 2026 Çarşamba)." },
  { id: "tr-a1.w078", t: "salı", pos: "n", n: "der Dienstag", ex: "Salı günü pazar kuruluyor.", exn: "Dienstags ist Markt.", topic: "numbers" },
  { id: "tr-a1.w079", t: "çarşamba", pos: "n", n: "der Mittwoch", ex: "Çarşamba akşamı boşum.", exn: "Mittwochabend habe ich Zeit.", topic: "numbers" },
  { id: "tr-a1.w080", t: "perşembe", pos: "n", n: "der Donnerstag", ex: "Perşembe günü doktora gidiyorum.", exn: "Am Donnerstag gehe ich zum Arzt.", topic: "numbers" },
  { id: "tr-a1.w081", t: "cuma", pos: "n", n: "der Freitag", ex: "Cuma günleri camiye gidiyor.", exn: "Freitags geht er in die Moschee.", topic: "numbers" },
  { id: "tr-a1.w082", t: "cumartesi", pos: "n", n: "der Samstag", ex: "Cumartesi sabahı geç kalkıyorum.", exn: "Am Samstagmorgen stehe ich spät auf.", topic: "numbers" },
  { id: "tr-a1.w083", t: "pazar", pos: "n", n: "der Sonntag; der Markt", ex: "Pazar günü ailemi ziyaret ediyorum.", exn: "Am Sonntag besuche ich meine Familie.", topic: "numbers", note: "pazar heißt auch „Markt“ (Wochenmarkt). Was gemeint ist, zeigt meist „günü“: pazar günü = am Sonntag." },

  /* ---------- Essen & Trinken (food) ---------- */
  { id: "tr-a1.w084", t: "su", pos: "n", n: "das Wasser", ex: "Bir şişe su alabilir miyim?", exn: "Kann ich eine Flasche Wasser haben?", topic: "food", note: "Unregelmäßig: Vor Endungen kommt ein y dazu – suyu, suyum (nicht „susu“)." },
  { id: "tr-a1.w085", t: "çay", pos: "n", n: "der Tee", ex: "Kahvaltıda iki bardak çay içiyorum.", exn: "Zum Frühstück trinke ich zwei Gläser Tee.", topic: "food" },
  { id: "tr-a1.w086", t: "kahve", pos: "n", n: "der Kaffee", ex: "Kahveyi şekerli mi içiyorsun?", exn: "Trinkst du den Kaffee mit Zucker?", topic: "food" },
  { id: "tr-a1.w087", t: "süt", pos: "n", n: "die Milch", ex: "Buzdolabında süt yok.", exn: "Im Kühlschrank ist keine Milch.", topic: "food", note: "Einsilbige Wörter erweichen meist nicht: süt → sütü (nicht „südü“)." },
  { id: "tr-a1.w088", t: "ekmek", pos: "n", n: "das Brot", ex: "Fırından taze ekmek aldım.", exn: "Ich habe beim Bäcker frisches Brot gekauft.", topic: "food", note: "Vor Vokal wird k zu ğ: ekmeği. Achtung: -mek sieht aus wie eine Infinitivendung, ekmek ist hier aber ein Nomen." },
  { id: "tr-a1.w089", t: "peynir", pos: "n", n: "der Käse", ex: "Kahvaltıda beyaz peynir yiyoruz.", exn: "Zum Frühstück essen wir Weißkäse.", topic: "food" },
  { id: "tr-a1.w090", t: "yumurta", pos: "n", n: "das Ei", ex: "Sabahları iki yumurta yiyorum.", exn: "Morgens esse ich zwei Eier.", topic: "food" },
  { id: "tr-a1.w091", t: "zeytin", pos: "n", n: "die Olive", ex: "Bu zeytinler çok lezzetli.", exn: "Diese Oliven sind sehr lecker.", topic: "food" },
  { id: "tr-a1.w092", t: "domates", pos: "n", n: "die Tomate", ex: "Pazardan bir kilo domates aldım.", exn: "Ich habe auf dem Markt ein Kilo Tomaten gekauft.", topic: "food", note: "Das s gehört zum Wort, es ist kein Plural: bir domates = eine Tomate." },
  { id: "tr-a1.w093", t: "elma", pos: "n", n: "der Apfel", ex: "Her gün bir elma yiyorum.", exn: "Ich esse jeden Tag einen Apfel.", topic: "food" },
  { id: "tr-a1.w094", t: "muz", pos: "n", n: "die Banane", ex: "Bir kilo muz kaç lira?", exn: "Was kostet ein Kilo Bananen?", topic: "food" },
  { id: "tr-a1.w095", t: "patates", pos: "n", n: "die Kartoffel", ex: "Akşam patates kızartması yapıyoruz.", exn: "Heute Abend machen wir Pommes.", topic: "food" },
  { id: "tr-a1.w096", t: "et", pos: "n", n: "das Fleisch", ex: "Ben et yemiyorum.", exn: "Ich esse kein Fleisch.", topic: "food", note: "„kein“ gibt es nicht als eigenes Wort – verneint wird das Verb: et yemiyorum." },
  { id: "tr-a1.w097", t: "tavuk", pos: "n", n: "das Hähnchen; das Huhn", ex: "Bugün tavuk pişiriyorum.", exn: "Heute koche ich Hähnchen.", topic: "food", note: "Vor Vokal wird k zu ğ: tavuğu." },
  { id: "tr-a1.w098", t: "balık", pos: "n", n: "der Fisch", ex: "Cuma akşamı balık yiyoruz.", exn: "Am Freitagabend essen wir Fisch.", topic: "food", note: "Vor Vokal wird k zu ğ: balığı." },
  { id: "tr-a1.w099", t: "pilav", pos: "n", n: "der Reis (gekocht); das Reisgericht", ex: "Pilav çok güzel olmuş.", exn: "Der Reis ist sehr gut geworden.", topic: "food", note: "Ungekochter Reis heißt pirinç." },
  { id: "tr-a1.w100", t: "çorba", pos: "n", n: "die Suppe", ex: "Önce bir mercimek çorbası alalım.", exn: "Lass uns zuerst eine Linsensuppe nehmen.", topic: "food" },
  { id: "tr-a1.w101", t: "salata", pos: "n", n: "der Salat", ex: "Salata ister misiniz?", exn: "Möchten Sie Salat?", topic: "food" },
  { id: "tr-a1.w102", t: "meyve", pos: "n", n: "das Obst; die Frucht", ex: "Masada bol meyve var.", exn: "Auf dem Tisch ist viel Obst.", topic: "food" },
  { id: "tr-a1.w103", t: "sebze", pos: "n", n: "das Gemüse", ex: "Her gün taze sebze yiyoruz.", exn: "Wir essen jeden Tag frisches Gemüse.", topic: "food" },
  { id: "tr-a1.w104", t: "şeker", pos: "n", n: "der Zucker; das Bonbon", ex: "Çayım şekersiz olsun, lütfen.", exn: "Meinen Tee bitte ohne Zucker.", topic: "food", note: "-li = mit, -siz = ohne: şekerli (mit Zucker), şekersiz (ohne Zucker)." },
  { id: "tr-a1.w105", t: "tuz", pos: "n", n: "das Salz", ex: "Tuzu uzatır mısın?", exn: "Reichst du mir das Salz?", topic: "food" },
  { id: "tr-a1.w106", t: "kahvaltı", pos: "n", n: "das Frühstück", ex: "Pazar günleri geç kahvaltı yapıyoruz.", exn: "Sonntags frühstücken wir spät.", topic: "food", note: "frühstücken = kahvaltı yapmak (wörtlich „Frühstück machen“)." },
  { id: "tr-a1.w107", t: "ayran", pos: "n", n: "der Ayran (salziges Joghurtgetränk)", ex: "Kebabın yanında ayran içiyoruz.", exn: "Zum Kebab trinken wir Ayran.", topic: "food" },
  { id: "tr-a1.w108", t: "yoğurt", pos: "n", n: "der Joghurt", ex: "Annem evde yoğurt yapıyor.", exn: "Meine Mutter macht Joghurt selbst.", topic: "food", note: "Das deutsche Wort „Joghurt“ stammt aus dem Türkischen. Das ğ ist stumm: „jo-urt“." },
  { id: "tr-a1.w109", t: "lokanta", pos: "n", n: "das (einfache) Restaurant", ex: "Öğlen küçük bir lokantada yiyoruz.", exn: "Mittags essen wir in einem kleinen Restaurant.", topic: "food", note: "Eine lokanta bietet einfache, warme Tagesgerichte. „restoran“ ist eher gehoben." },
  { id: "tr-a1.w110", t: "bardak", pos: "n", n: "das Glas (Trinkglas)", ex: "Bir bardak su, lütfen.", exn: "Ein Glas Wasser, bitte.", topic: "food", note: "Vor Vokal wird k zu ğ: bardağı. Das Material Glas heißt dagegen cam." },
  { id: "tr-a1.w111", t: "hesap", pos: "n", n: "die Rechnung", ex: "Hesap, lütfen!", exn: "Die Rechnung, bitte!", topic: "food", note: "Vor Vokal wird p zu b: hesabı." },
  { id: "tr-a1.w112", t: "aç", pos: "adj", n: "hungrig", ex: "Çok açım, yemek ne zaman hazır?", exn: "Ich habe großen Hunger, wann ist das Essen fertig?", topic: "food", note: "Im Türkischen „ist“ man hungrig: açım (ich bin hungrig). aç! heißt außerdem „Mach auf!“ (von açmak)." },
  { id: "tr-a1.w113", t: "tok", pos: "adj", n: "satt", ex: "Teşekkürler, ben tokum.", exn: "Danke, ich bin satt.", topic: "food" },
  { id: "tr-a1.w114", t: "lezzetli", pos: "adj", n: "lecker", ex: "Bu çorba çok lezzetli!", exn: "Diese Suppe ist sehr lecker!", topic: "food" },
  { id: "tr-a1.w115", t: "kebap", pos: "n", n: "der Kebab", ex: "Bu lokantanın kebabı çok meşhur.", exn: "Der Kebab in diesem Restaurant ist sehr bekannt.", topic: "food", note: "Nach TDK schreibt man kebap (mit p). Vor Vokal wird p zu b: kebabı." },

  /* ---------- Wohnen & Haushalt (home) ---------- */
  { id: "tr-a1.w116", t: "ev", pos: "n", n: "das Haus; die Wohnung; das Zuhause", ex: "Evim çok büyük değil.", exn: "Mein Haus ist nicht sehr groß.", topic: "home", note: "evde = zu Hause, eve = nach Hause, evden = von zu Hause." },
  { id: "tr-a1.w117", t: "daire", pos: "n", n: "die Wohnung", ex: "Üç odalı bir dairede oturuyoruz.", exn: "Wir wohnen in einer Dreizimmerwohnung.", topic: "home" },
  { id: "tr-a1.w118", t: "oda", pos: "n", n: "das Zimmer", ex: "Benim odam küçük ama aydınlık.", exn: "Mein Zimmer ist klein, aber hell.", topic: "home" },
  { id: "tr-a1.w119", t: "mutfak", pos: "n", n: "die Küche", ex: "Annem mutfakta.", exn: "Meine Mutter ist in der Küche.", topic: "home", note: "Vor Vokal wird k zu ğ: mutfağı. Aber: mutfakta (vor Konsonant bleibt k)." },
  { id: "tr-a1.w120", t: "banyo", pos: "n", n: "das Bad; das Badezimmer", ex: "Banyo koridorun sonunda.", exn: "Das Bad ist am Ende des Flurs.", topic: "home" },
  { id: "tr-a1.w121", t: "tuvalet", pos: "n", n: "die Toilette", ex: "Tuvalet ikinci katta.", exn: "Die Toilette ist im zweiten Stock.", topic: "home" },
  { id: "tr-a1.w122", t: "salon", pos: "n", n: "das Wohnzimmer", ex: "Misafirler salonda oturuyor.", exn: "Die Gäste sitzen im Wohnzimmer.", topic: "home", note: "salon ist oft das „gute“ Wohnzimmer für Gäste; für die Familie sagt man oturma odası." },
  { id: "tr-a1.w123", t: "yatak", pos: "n", n: "das Bett", ex: "Bu yatak çok rahat.", exn: "Dieses Bett ist sehr bequem.", topic: "home", note: "yatak odası = das Schlafzimmer. Vor Vokal: yatağı." },
  { id: "tr-a1.w124", t: "kapı", pos: "n", n: "die Tür", ex: "Kapı açık, kim geldi?", exn: "Die Tür ist offen, wer ist gekommen?", topic: "home" },
  { id: "tr-a1.w125", t: "pencere", pos: "n", n: "das Fenster", ex: "Pencereyi açabilir miyim?", exn: "Darf ich das Fenster öffnen?", topic: "home" },
  { id: "tr-a1.w126", t: "masa", pos: "n", n: "der Tisch", ex: "Yemek masada.", exn: "Das Essen steht auf dem Tisch.", topic: "home" },
  { id: "tr-a1.w127", t: "sandalye", pos: "n", n: "der Stuhl", ex: "Mutfakta dört sandalye var.", exn: "In der Küche stehen vier Stühle.", topic: "home" },
  { id: "tr-a1.w128", t: "koltuk", pos: "n", n: "der Sessel; der Sitzplatz", ex: "Babam koltukta uyuyor.", exn: "Papa schläft im Sessel.", topic: "home", note: "Vor Vokal wird k zu ğ: koltuğu. Im Bus oder Flugzeug heißt koltuk „Sitzplatz“." },
  { id: "tr-a1.w129", t: "dolap", pos: "n", n: "der Schrank", ex: "Bardaklar dolapta.", exn: "Die Gläser sind im Schrank.", topic: "home", note: "Vor Vokal wird p zu b: dolabı." },
  { id: "tr-a1.w130", t: "buzdolabı", pos: "n", n: "der Kühlschrank", ex: "Buzdolabı boş, alışverişe gidelim.", exn: "Der Kühlschrank ist leer, lass uns einkaufen gehen.", topic: "home", note: "buz (Eis) + dolap (Schrank) → buzdolabı, zusammengeschrieben." },
  { id: "tr-a1.w131", t: "anahtar", pos: "n", n: "der Schlüssel", ex: "Anahtarımı bulamıyorum.", exn: "Ich finde meinen Schlüssel nicht.", topic: "home" },
  { id: "tr-a1.w132", t: "lamba", pos: "n", n: "die Lampe", ex: "Salondaki lamba bozuk.", exn: "Die Lampe im Wohnzimmer ist kaputt.", topic: "home" },
  { id: "tr-a1.w133", t: "televizyon", pos: "n", n: "der Fernseher; das Fernsehen", ex: "Akşamları televizyon izliyoruz.", exn: "Abends sehen wir fern.", topic: "home" },
  { id: "tr-a1.w134", t: "bahçe", pos: "n", n: "der Garten", ex: "Bahçede bir elma ağacı var.", exn: "Im Garten steht ein Apfelbaum.", topic: "home" },
  { id: "tr-a1.w135", t: "balkon", pos: "n", n: "der Balkon", ex: "Yazın balkonda kahvaltı yapıyoruz.", exn: "Im Sommer frühstücken wir auf dem Balkon.", topic: "home" },
  { id: "tr-a1.w136", t: "kira", pos: "n", n: "die Miete", ex: "Kira ayda on beş bin lira.", exn: "Die Miete beträgt fünfzehntausend Lira im Monat.", topic: "home" },
  { id: "tr-a1.w137", t: "kat", pos: "n", n: "das Stockwerk; die Etage", ex: "Üçüncü katta oturuyoruz.", exn: "Wir wohnen im dritten Stock.", topic: "home", note: "Einsilbig, daher keine Erweichung: katı, katta." },
  { id: "tr-a1.w138", t: "temizlik", pos: "n", n: "das Putzen; die Sauberkeit", ex: "Cumartesi günü temizlik yapıyoruz.", exn: "Samstags putzen wir.", topic: "home", note: "putzen = temizlik yapmak. Vor Vokal wird k zu ğ: temizliği." },
  { id: "tr-a1.w139", t: "bulaşık", pos: "n", n: "das schmutzige Geschirr; der Abwasch", ex: "Bulaşıkları kim yıkıyor?", exn: "Wer spült das Geschirr?", topic: "home", note: "abwaschen = bulaşık yıkamak." },

  /* ---------- Stadt, Wege & Verkehr (city) ---------- */
  { id: "tr-a1.w140", t: "şehir", pos: "n", n: "die Stadt", ex: "İstanbul çok büyük bir şehir.", exn: "Istanbul ist eine sehr große Stadt.", topic: "city", note: "Vor Vokal fällt das i weg: şehir → şehri, şehrim." },
  { id: "tr-a1.w141", t: "köy", pos: "n", n: "das Dorf", ex: "Yazın köye gidiyoruz.", exn: "Im Sommer fahren wir ins Dorf.", topic: "city" },
  { id: "tr-a1.w142", t: "sokak", pos: "n", n: "die Straße; die Gasse", ex: "Hangi sokakta oturuyorsun?", exn: "In welcher Straße wohnst du?", topic: "city", note: "sokak = kleinere Straße, cadde = Hauptstraße. Vor Vokal: sokağı." },
  { id: "tr-a1.w143", t: "cadde", pos: "n", n: "die Hauptstraße", ex: "Bu cadde çok kalabalık.", exn: "Auf dieser Straße ist viel los.", topic: "city" },
  { id: "tr-a1.w144", t: "yol", pos: "n", n: "der Weg; die Straße", ex: "Yolu biliyor musun?", exn: "Kennst du den Weg?", topic: "city" },
  { id: "tr-a1.w145", t: "durak", pos: "n", n: "die Haltestelle", ex: "Otobüs durağı okulun önünde.", exn: "Die Bushaltestelle ist vor der Schule.", topic: "city", note: "Vor Vokal wird k zu ğ: otobüs durağı." },
  { id: "tr-a1.w146", t: "otobüs", pos: "n", n: "der Bus", ex: "Okula otobüsle gidiyorum.", exn: "Ich fahre mit dem Bus zur Schule.", topic: "city", note: "„mit“ ist eine Endung: otobüsle, trenle, arabayla (nach Vokal mit y)." },
  { id: "tr-a1.w147", t: "araba", pos: "n", n: "das Auto", ex: "Yeni bir araba almak istiyorum.", exn: "Ich möchte ein neues Auto kaufen.", topic: "city" },
  { id: "tr-a1.w148", t: "taksi", pos: "n", n: "das Taxi", ex: "Bana bir taksi çağırır mısınız?", exn: "Können Sie mir ein Taxi rufen?", topic: "city" },
  { id: "tr-a1.w149", t: "dolmuş", pos: "n", n: "der Dolmuş (Sammeltaxi)", ex: "Dolmuş kaçta kalkıyor?", exn: "Wann fährt der Dolmuş ab?", topic: "city", note: "Kleinbus mit fester Strecke, hält auf Zuruf. Wörtlich: „gefüllt“ – er fährt oft erst los, wenn er voll ist." },
  { id: "tr-a1.w150", t: "tren", pos: "n", n: "der Zug", ex: "Tren saat onda kalkıyor.", exn: "Der Zug fährt um zehn Uhr ab.", topic: "city" },
  { id: "tr-a1.w151", t: "istasyon", pos: "n", n: "der Bahnhof; die Station", ex: "Tren istasyonu nerede?", exn: "Wo ist der Bahnhof?", topic: "city" },
  { id: "tr-a1.w152", t: "havalimanı", pos: "n", n: "der Flughafen", ex: "Havalimanına metroyla gidiyorum.", exn: "Ich fahre mit der U-Bahn zum Flughafen.", topic: "city", note: "Auch: havaalanı. Beide zusammengeschrieben." },
  { id: "tr-a1.w153", t: "bilet", pos: "n", n: "die Fahrkarte; das Ticket", ex: "Bilet ne kadar?", exn: "Was kostet die Fahrkarte?", topic: "city" },
  { id: "tr-a1.w154", t: "banka", pos: "n", n: "die Bank (Geldinstitut)", ex: "Banka saat beşte kapanıyor.", exn: "Die Bank schließt um fünf.", topic: "city", note: "Nur das Geldinstitut! Die Sitzbank heißt bank." },
  { id: "tr-a1.w155", t: "cami", pos: "n", n: "die Moschee", ex: "Köşedeki cami çok eski.", exn: "Die Moschee an der Ecke ist sehr alt.", topic: "city", note: "Gesprochen „dschami“. Mit Endung: camiye, camide." },
  { id: "tr-a1.w156", t: "otel", pos: "n", n: "das Hotel", ex: "Otelimiz denize yakın.", exn: "Unser Hotel liegt in Meeresnähe.", topic: "city" },
  { id: "tr-a1.w157", t: "park", pos: "n", n: "der Park", ex: "Parkta piknik yapıyoruz.", exn: "Wir machen ein Picknick im Park.", topic: "city" },
  { id: "tr-a1.w158", t: "sağ", pos: "x", n: "rechts; die rechte Seite", ex: "Banka sağda, eczanenin yanında.", exn: "Die Bank ist rechts, neben der Apotheke.", topic: "city", note: "sağda = (auf der) rechts(en Seite), sağa = nach rechts. sağ heißt auch „lebendig, gesund“ (sağ ol)." },
  { id: "tr-a1.w159", t: "sol", pos: "x", n: "links; die linke Seite", ex: "Eczane solda.", exn: "Die Apotheke ist links.", topic: "city", note: "solda = links (Ort), sola = nach links (Richtung)." },
  { id: "tr-a1.w160", t: "düz", pos: "adj", n: "geradeaus; gerade, flach", ex: "Bu yoldan dümdüz gidin.", exn: "Gehen Sie diese Straße immer geradeaus.", topic: "city", note: "dümdüz = ganz gerade, immer geradeaus (verstärkte Form)." },
  { id: "tr-a1.w161", t: "köşe", pos: "n", n: "die Ecke", ex: "Köşede bir fırın var.", exn: "An der Ecke gibt es eine Bäckerei.", topic: "city" },
  { id: "tr-a1.w162", t: "yakın", pos: "adj", n: "nah; in der Nähe", ex: "Ev okula çok yakın.", exn: "Das Haus ist ganz nah an der Schule.", topic: "city", note: "„nah an etwas“ mit Dativ: okula yakın." },
  { id: "tr-a1.w163", t: "uzak", pos: "adj", n: "weit (entfernt)", ex: "Market buradan uzak değil.", exn: "Der Supermarkt ist nicht weit von hier.", topic: "city", note: "„weit weg von“ mit Ablativ: buradan uzak (von hier weit)." },

  /* ---------- Einkaufen & Kleidung (shop) ---------- */
  { id: "tr-a1.w164", t: "market", pos: "n", n: "der Supermarkt", ex: "Markete gidiyorum, bir şey lazım mı?", exn: "Ich gehe zum Supermarkt, brauchst du etwas?", topic: "shop", note: "Ein Wochenmarkt ist kein market, sondern ein pazar." },
  { id: "tr-a1.w165", t: "bakkal", pos: "n", n: "der kleine Lebensmittelladen; der Tante-Emma-Laden", ex: "Köşedeki bakkaldan ekmek al.", exn: "Hol Brot im Laden an der Ecke.", topic: "shop" },
  { id: "tr-a1.w166", t: "fırın", pos: "n", n: "die Bäckerei; der Backofen", ex: "Sabahları fırının önünde kuyruk var.", exn: "Morgens gibt es vor der Bäckerei eine Schlange.", topic: "shop" },
  { id: "tr-a1.w167", t: "mağaza", pos: "n", n: "das Geschäft; der Laden", ex: "Mağaza saat onda açılıyor.", exn: "Das Geschäft öffnet um zehn Uhr.", topic: "shop" },
  { id: "tr-a1.w168", t: "para", pos: "n", n: "das Geld", ex: "Yanımda hiç para yok.", exn: "Ich habe gar kein Geld dabei.", topic: "shop" },
  { id: "tr-a1.w169", t: "lira", pos: "n", n: "die Lira", ex: "Bir lirada yüz kuruş var.", exn: "Eine Lira hat hundert Kuruş.", topic: "shop" },
  { id: "tr-a1.w170", t: "fiyat", pos: "n", n: "der Preis", ex: "Fiyatı biraz yüksek.", exn: "Der Preis ist etwas hoch.", topic: "shop" },
  { id: "tr-a1.w171", t: "ne kadar", pos: "phr", n: "wie viel; was kostet …?", ex: "Bu elbise ne kadar?", exn: "Was kostet dieses Kleid?", topic: "shop", note: "Auf dem Markt fragt man oft auch: „Kaç lira?“ (Wie viel Lira?)." },
  { id: "tr-a1.w172", t: "ucuz", pos: "adj", n: "billig; günstig", ex: "Pazarda her şey daha ucuz.", exn: "Auf dem Markt ist alles billiger.", topic: "shop" },
  { id: "tr-a1.w173", t: "pahalı", pos: "adj", n: "teuer", ex: "İstanbul'da kiralar çok pahalı.", exn: "In Istanbul sind die Mieten sehr teuer.", topic: "shop" },
  { id: "tr-a1.w174", t: "kilo", pos: "n", n: "das Kilo", ex: "İki kilo patates, lütfen.", exn: "Zwei Kilo Kartoffeln, bitte.", topic: "shop", note: "Nach Zahlen kein Plural – weder bei kilo noch bei patates." },
  { id: "tr-a1.w175", t: "kredi kartı", pos: "n", n: "die Kreditkarte", ex: "Kredi kartıyla ödeyebilir miyim?", exn: "Kann ich mit Kreditkarte bezahlen?", topic: "shop" },
  { id: "tr-a1.w176", t: "nakit", pos: "n", n: "das Bargeld; bar", ex: "Sadece nakit kabul ediyoruz.", exn: "Wir nehmen nur Bargeld.", topic: "shop" },
  { id: "tr-a1.w177", t: "elbise", pos: "n", n: "das Kleid", ex: "Bu elbiseyi deneyebilir miyim?", exn: "Kann ich dieses Kleid anprobieren?", topic: "shop", note: "Im Plural (elbiseler) oft allgemein „Kleidung“." },
  { id: "tr-a1.w178", t: "gömlek", pos: "n", n: "das Hemd", ex: "Bu gömleğin mavisi var mı?", exn: "Gibt es dieses Hemd auch in Blau?", topic: "shop", note: "Vor Vokal wird k zu ğ: gömleği." },
  { id: "tr-a1.w179", t: "pantolon", pos: "n", n: "die Hose", ex: "Bu pantolon bana büyük.", exn: "Diese Hose ist mir zu groß.", topic: "shop", note: "Wie im Deutschen Singular: bir pantolon = eine Hose." },
  { id: "tr-a1.w180", t: "ayakkabı", pos: "n", n: "der Schuh; das Paar Schuhe", ex: "Yeni ayakkabılarım çok rahat.", exn: "Meine neuen Schuhe sind sehr bequem.", topic: "shop", note: "ayak (Fuß) + kap (Behälter): zusammengeschrieben, mit zwei k." },
  { id: "tr-a1.w181", t: "ceket", pos: "n", n: "die Jacke; das Jackett", ex: "Hava soğuk, ceketini al.", exn: "Es ist kalt, nimm deine Jacke mit.", topic: "shop" },
  { id: "tr-a1.w182", t: "beden", pos: "n", n: "die Größe (Kleidung); der Körper", ex: "Hangi beden giyiyorsunuz?", exn: "Welche Größe tragen Sie?", topic: "shop" },
  { id: "tr-a1.w183", t: "renk", pos: "n", n: "die Farbe", ex: "En sevdiğin renk ne?", exn: "Was ist deine Lieblingsfarbe?", topic: "shop", note: "Vor Vokal wird nk zu ng: renk → rengi." },

  /* ---------- Arbeit, Schule & Ämter (work) ---------- */
  { id: "tr-a1.w184", t: "iş", pos: "n", n: "die Arbeit; der Job", ex: "Yeni bir iş arıyorum.", exn: "Ich suche eine neue Arbeit.", topic: "work", note: "zur Arbeit gehen = işe gitmek." },
  { id: "tr-a1.w185", t: "okul", pos: "n", n: "die Schule", ex: "Okul saat sekizde başlıyor.", exn: "Die Schule fängt um acht an.", topic: "work" },
  { id: "tr-a1.w186", t: "öğretmen", pos: "n", n: "der Lehrer / die Lehrerin", ex: "Öğretmenimiz çok sabırlı.", exn: "Unsere Lehrerin ist sehr geduldig.", topic: "work", note: "Berufe haben kein grammatisches Geschlecht: öğretmen = Lehrer oder Lehrerin." },
  { id: "tr-a1.w187", t: "öğrenci", pos: "n", n: "der Schüler / die Schülerin; der Student / die Studentin", ex: "Ben üniversite öğrencisiyim.", exn: "Ich bin Student.", topic: "work" },
  { id: "tr-a1.w188", t: "ders", pos: "n", n: "der Unterricht; die Unterrichtsstunde", ex: "Ders kaçta bitiyor?", exn: "Wann ist der Unterricht zu Ende?", topic: "work" },
  { id: "tr-a1.w189", t: "sınıf", pos: "n", n: "die Klasse; das Klassenzimmer", ex: "Sınıfımız ikinci katta.", exn: "Unser Klassenzimmer ist im zweiten Stock.", topic: "work" },
  { id: "tr-a1.w190", t: "kitap", pos: "n", n: "das Buch", ex: "Bu kitabı okudun mu?", exn: "Hast du dieses Buch gelesen?", topic: "work", note: "Vor Vokal wird p zu b: kitap → kitabı. Vor Konsonant bleibt p: kitaplar." },
  { id: "tr-a1.w191", t: "kalem", pos: "n", n: "der Stift", ex: "Bir kalem verir misin?", exn: "Gibst du mir einen Stift?", topic: "work" },
  { id: "tr-a1.w192", t: "soru", pos: "n", n: "die Frage", ex: "Bir sorum var.", exn: "Ich habe eine Frage.", topic: "work" },
  { id: "tr-a1.w193", t: "cevap", pos: "n", n: "die Antwort", ex: "Cevabı biliyorum!", exn: "Ich weiß die Antwort!", topic: "work", note: "Vor Vokal wird p zu b: cevabı. Gleichbedeutend: yanıt." },
  { id: "tr-a1.w194", t: "sınav", pos: "n", n: "die Prüfung", ex: "Yarın sınavım var.", exn: "Morgen habe ich eine Prüfung.", topic: "work" },
  { id: "tr-a1.w195", t: "Türkçe", pos: "n", n: "das Türkisch (Sprache)", ex: "Türkçe öğreniyorum.", exn: "Ich lerne Türkisch.", topic: "work", note: "Sprachnamen mit -ce/-çe bekommen keinen Apostroph: Türkçede, Türkçeyi (nicht „Türkçe'de“)." },
  { id: "tr-a1.w196", t: "Almanca", pos: "n", n: "das Deutsch (Sprache)", ex: "Almanca biliyor musunuz?", exn: "Sprechen Sie Deutsch?", topic: "work", note: "„Eine Sprache sprechen können“ heißt meist bilmek: Almanca biliyorum." },
  { id: "tr-a1.w197", t: "ofis", pos: "n", n: "das Büro", ex: "Bugün ofiste değilim, evden çalışıyorum.", exn: "Heute bin ich nicht im Büro, ich arbeite von zu Hause.", topic: "work" },
  { id: "tr-a1.w198", t: "patron", pos: "n", n: "der Chef / die Chefin", ex: "Patronum bugün izinli.", exn: "Mein Chef hat heute frei.", topic: "work", note: "Falscher Freund: patron ist nicht der „Patron“ (Schutzheilige), sondern der Chef." },
  { id: "tr-a1.w199", t: "iş arkadaşı", pos: "n", n: "der Kollege / die Kollegin", ex: "İş arkadaşlarım çok yardımsever.", exn: "Meine Kollegen sind sehr hilfsbereit.", topic: "work", note: "Mit Possessiv: iş arkadaşım (mein Kollege) – das -ı fällt dabei weg." },
  { id: "tr-a1.w200", t: "toplantı", pos: "n", n: "die Besprechung; das Meeting", ex: "Toplantı uzun sürdü.", exn: "Die Besprechung hat lange gedauert.", topic: "work" },
  { id: "tr-a1.w201", t: "pasaport", pos: "n", n: "der Reisepass", ex: "Pasaportunuzu görebilir miyim?", exn: "Darf ich Ihren Pass sehen?", topic: "work" },
  { id: "tr-a1.w202", t: "kimlik", pos: "n", n: "der Personalausweis", ex: "Kimliğinizi unutmayın.", exn: "Vergessen Sie Ihren Ausweis nicht.", topic: "work", note: "Vor Vokal wird k zu ğ: kimliği." },
  { id: "tr-a1.w203", t: "adres", pos: "n", n: "die Adresse", ex: "Adresiniz nedir?", exn: "Wie ist Ihre Adresse?", topic: "work" },
  { id: "tr-a1.w204", t: "telefon", pos: "n", n: "das Telefon; das Handy", ex: "Telefon numaranızı alabilir miyim?", exn: "Kann ich Ihre Telefonnummer haben?", topic: "work", note: "Handy heißt auch cep telefonu (wörtlich: Taschentelefon)." },
  { id: "tr-a1.w205", t: "bilgisayar", pos: "n", n: "der Computer", ex: "Bilgisayarım çok yavaş.", exn: "Mein Computer ist sehr langsam.", topic: "work" },

  /* ---------- Körper & Gesundheit (body) ---------- */
  { id: "tr-a1.w206", t: "baş", pos: "n", n: "der Kopf", ex: "Başım ağrıyor.", exn: "Ich habe Kopfschmerzen.", topic: "body", note: "Schmerzen sagt man so: Körperteil + mein + ağrıyor (tut weh). Umgangssprachlich auch kafa." },
  { id: "tr-a1.w207", t: "göz", pos: "n", n: "das Auge", ex: "Gözlerin çok güzel.", exn: "Deine Augen sind sehr schön.", topic: "body" },
  { id: "tr-a1.w208", t: "kulak", pos: "n", n: "das Ohr", ex: "Kulağım iyi duymuyor.", exn: "Ich höre auf dem Ohr nicht gut.", topic: "body", note: "Vor Vokal wird k zu ğ: kulağım." },
  { id: "tr-a1.w209", t: "burun", pos: "n", n: "die Nase", ex: "Burnum akıyor.", exn: "Meine Nase läuft.", topic: "body", note: "Vor Vokal fällt das u weg: burun → burnum." },
  { id: "tr-a1.w210", t: "ağız", pos: "n", n: "der Mund", ex: "Ağzını aç, lütfen.", exn: "Mach bitte den Mund auf.", topic: "body", note: "Vor Vokal fällt das ı weg: ağız → ağzım, ağzını." },
  { id: "tr-a1.w211", t: "diş", pos: "n", n: "der Zahn", ex: "Yemekten sonra dişlerini fırçala.", exn: "Putz dir nach dem Essen die Zähne.", topic: "body" },
  { id: "tr-a1.w212", t: "el", pos: "n", n: "die Hand", ex: "Yemekten önce ellerini yıka.", exn: "Wasch dir vor dem Essen die Hände.", topic: "body" },
  { id: "tr-a1.w213", t: "kol", pos: "n", n: "der Arm", ex: "Kolumu kırdım.", exn: "Ich habe mir den Arm gebrochen.", topic: "body" },
  { id: "tr-a1.w214", t: "bacak", pos: "n", n: "das Bein", ex: "Futboldan sonra bacaklarım yorgun.", exn: "Nach dem Fußball sind meine Beine müde.", topic: "body" },
  { id: "tr-a1.w215", t: "ayak", pos: "n", n: "der Fuß", ex: "Bütün gün yürüdük, ayaklarım ağrıyor.", exn: "Wir sind den ganzen Tag gelaufen, mir tun die Füße weh.", topic: "body", note: "Vor Vokal wird k zu ğ: ayağım." },
  { id: "tr-a1.w216", t: "karın", pos: "n", n: "der Bauch", ex: "Karnım aç.", exn: "Ich habe Hunger.", topic: "body", note: "Vor Vokal fällt das ı weg: karın → karnım. „Karnım aç“ heißt wörtlich „Mein Bauch ist hungrig“." },
  { id: "tr-a1.w217", t: "hasta", pos: "adj", n: "krank; der Patient / die Patientin", ex: "Bugün hastayım, işe gidemiyorum.", exn: "Ich bin heute krank und kann nicht zur Arbeit.", topic: "body" },
  { id: "tr-a1.w218", t: "doktor", pos: "n", n: "der Arzt / die Ärztin", ex: "Doktora gitmen lazım.", exn: "Du musst zum Arzt gehen.", topic: "body", note: "Auch: hekim. Ärzte spricht man oft mit „Doktor Bey“ / „Doktor Hanım“ oder „Hocam“ an." },
  { id: "tr-a1.w219", t: "hastane", pos: "n", n: "das Krankenhaus", ex: "Hastane buraya yakın mı?", exn: "Ist das Krankenhaus hier in der Nähe?", topic: "body" },
  { id: "tr-a1.w220", t: "eczane", pos: "n", n: "die Apotheke", ex: "Nöbetçi eczane nerede?", exn: "Wo ist die Notdienstapotheke?", topic: "body", note: "nöbetçi eczane = Apotheke mit Nacht- oder Sonntagsdienst." },
  { id: "tr-a1.w221", t: "ilaç", pos: "n", n: "das Medikament", ex: "Bu ilacı günde üç kez alın.", exn: "Nehmen Sie dieses Medikament dreimal täglich.", topic: "body", note: "Vor Vokal wird ç zu c: ilacı." },
  { id: "tr-a1.w222", t: "ateş", pos: "n", n: "das Fieber; das Feuer", ex: "Çocuğun ateşi var.", exn: "Das Kind hat Fieber.", topic: "body" },
  { id: "tr-a1.w223", t: "ağrı", pos: "n", n: "der Schmerz", ex: "Ağrı kesici var mı?", exn: "Haben Sie ein Schmerzmittel?", topic: "body", note: "Das Verb dazu: ağrımak (wehtun) – Dişim ağrıyor (Mein Zahn tut weh)." },
  { id: "tr-a1.w224", t: "yorgun", pos: "adj", n: "müde; erschöpft", ex: "Bugün çok yorgunum.", exn: "Ich bin heute sehr müde.", topic: "body", note: "Müde im Sinne von schläfrig: uykum var (wörtlich: „Ich habe Schlaf“)." },
  { id: "tr-a1.w225", t: "geçmiş olsun", pos: "phr", n: "Gute Besserung!", ex: "Geçmiş olsun, çabuk iyileş!", exn: "Gute Besserung, werd schnell wieder gesund!", topic: "body", note: "Wörtlich „Möge es vorbei sein“. Sagt man nicht nur bei Krankheit, sondern auch nach Unfällen oder Ärger." },

  /* ---------- Freizeit, Wetter & Natur (free) ---------- */
  { id: "tr-a1.w226", t: "hava", pos: "n", n: "das Wetter; die Luft", ex: "Bugün hava çok güzel.", exn: "Heute ist das Wetter sehr schön.", topic: "free" },
  { id: "tr-a1.w227", t: "güneş", pos: "n", n: "die Sonne", ex: "Bugün güneş var ama hava serin.", exn: "Heute scheint die Sonne, aber es ist kühl.", topic: "free" },
  { id: "tr-a1.w228", t: "yağmur", pos: "n", n: "der Regen", ex: "Yağmur yağıyor, şemsiyeni al.", exn: "Es regnet, nimm deinen Schirm mit.", topic: "free", note: "„Es regnet“ = yağmur yağıyor (wörtlich: „Regen fällt“). Ebenso: kar yağıyor (es schneit)." },
  { id: "tr-a1.w229", t: "kar", pos: "n", n: "der Schnee", ex: "Kışın dağlarda kar var.", exn: "Im Winter liegt in den Bergen Schnee.", topic: "free", note: "kâr (mit Dach-â) ist ein anderes Wort: der Gewinn." },
  { id: "tr-a1.w230", t: "rüzgâr", pos: "n", n: "der Wind", ex: "Bugün rüzgâr çok sert.", exn: "Heute ist der Wind sehr stark.", topic: "free", note: "Nach TDK mit â geschrieben: rüzgâr. Man sieht aber oft auch „rüzgar“." },
  { id: "tr-a1.w231", t: "sıcak", pos: "adj", n: "warm; heiß", ex: "Yazın burası çok sıcak.", exn: "Im Sommer ist es hier sehr heiß.", topic: "free", note: "Beginnt mit s + ı (ohne Punkt). Vor Vokal: sıcağı." },
  { id: "tr-a1.w232", t: "soğuk", pos: "adj", n: "kalt", ex: "Su çok soğuk, girmiyorum.", exn: "Das Wasser ist sehr kalt, ich gehe nicht rein.", topic: "free", note: "Das ğ ist stumm: „so-uk“." },
  { id: "tr-a1.w233", t: "yaz", pos: "n", n: "der Sommer", ex: "Yaz tatili ne zaman başlıyor?", exn: "Wann beginnen die Sommerferien?", topic: "free", note: "yazın = im Sommer. yaz! heißt auch „Schreib!“ (von yazmak)." },
  { id: "tr-a1.w234", t: "kış", pos: "n", n: "der Winter", ex: "Bu kış çok soğuk geçti.", exn: "Dieser Winter war sehr kalt.", topic: "free", note: "kışın = im Winter." },
  { id: "tr-a1.w235", t: "ilkbahar", pos: "n", n: "der Frühling", ex: "İlkbaharda her yer yeşil.", exn: "Im Frühling ist alles grün.", topic: "free", note: "Oft auch nur: bahar." },
  { id: "tr-a1.w236", t: "sonbahar", pos: "n", n: "der Herbst", ex: "Sonbaharda yapraklar sararıyor.", exn: "Im Herbst werden die Blätter gelb.", topic: "free" },
  { id: "tr-a1.w237", t: "deniz", pos: "n", n: "das Meer", ex: "Denizde yüzmeyi seviyorum.", exn: "Ich schwimme gern im Meer.", topic: "free" },
  { id: "tr-a1.w238", t: "dağ", pos: "n", n: "der Berg", ex: "Hafta sonu dağa çıkıyoruz.", exn: "Am Wochenende gehen wir in die Berge.", topic: "free", note: "Das ğ dehnt das a: „daa“." },
  { id: "tr-a1.w239", t: "ağaç", pos: "n", n: "der Baum", ex: "Bu ağaç çok yaşlı.", exn: "Dieser Baum ist sehr alt.", topic: "free", note: "Vor Vokal wird ç zu c: ağacı." },
  { id: "tr-a1.w240", t: "çiçek", pos: "n", n: "die Blume", ex: "Anneme çiçek aldım.", exn: "Ich habe meiner Mutter Blumen gekauft.", topic: "free", note: "Vor Vokal wird k zu ğ: çiçeği." },
  { id: "tr-a1.w241", t: "tatil", pos: "n", n: "der Urlaub; die Ferien", ex: "Tatilde Antalya'ya gidiyoruz.", exn: "Im Urlaub fahren wir nach Antalya.", topic: "free" },
  { id: "tr-a1.w242", t: "hafta sonu", pos: "n", n: "das Wochenende", ex: "Hafta sonu ne yapıyorsun?", exn: "Was machst du am Wochenende?", topic: "free", note: "Getrennt geschrieben: hafta sonu (nicht „haftasonu“)." },
  { id: "tr-a1.w243", t: "futbol", pos: "n", n: "der Fußball", ex: "Cumartesi futbol maçı var.", exn: "Am Samstag gibt es ein Fußballspiel.", topic: "free" },
  { id: "tr-a1.w244", t: "müzik", pos: "n", n: "die Musik", ex: "Arabada müzik dinliyorum.", exn: "Im Auto höre ich Musik.", topic: "free", note: "Musik hören = müzik dinlemek (nicht duymak)." },
  { id: "tr-a1.w245", t: "film", pos: "n", n: "der Film", ex: "Bu akşam televizyonda güzel bir film var.", exn: "Heute Abend läuft ein guter Film im Fernsehen.", topic: "free" },
  { id: "tr-a1.w246", t: "sinema", pos: "n", n: "das Kino", ex: "Sinemaya birlikte gidelim mi?", exn: "Wollen wir zusammen ins Kino gehen?", topic: "free" },
  { id: "tr-a1.w247", t: "spor", pos: "n", n: "der Sport", ex: "Haftada iki kez spor yapıyorum.", exn: "Ich mache zweimal pro Woche Sport.", topic: "free", note: "Sport treiben = spor yapmak." },
  { id: "tr-a1.w248", t: "yürüyüş", pos: "n", n: "der Spaziergang; die Wanderung", ex: "Akşam yemeğinden sonra yürüyüşe çıkıyoruz.", exn: "Nach dem Abendessen gehen wir spazieren.", topic: "free" },
  { id: "tr-a1.w249", t: "fotoğraf", pos: "n", n: "das Foto", ex: "Bir fotoğrafımızı çeker misiniz?", exn: "Können Sie ein Foto von uns machen?", topic: "free", note: "fotografieren = fotoğraf çekmek (wörtlich „ein Foto ziehen“)." },

  /* ---------- Wichtige Verben (verbs) ---------- */
  { id: "tr-a1.w250", t: "olmak", pos: "v", n: "sein; werden", ex: "Doktor olmak istiyorum.", exn: "Ich möchte Arzt werden.", topic: "verbs", note: "Im Präsens ist „sein“ meist nur eine Endung (Öğretmenim = Ich bin Lehrer). Aorist unregelmäßig: olur." },
  { id: "tr-a1.w251", t: "gitmek", pos: "v", n: "gehen; fahren", ex: "Yarın okula gidiyorum.", exn: "Morgen gehe ich zur Schule.", topic: "verbs", note: "Vor Vokal wird t zu d: gidiyorum. Das Ziel steht im Dativ: okula, eve." },
  { id: "tr-a1.w252", t: "gelmek", pos: "v", n: "kommen", ex: "Saat kaçta geliyorsun?", exn: "Um wie viel Uhr kommst du?", topic: "verbs", note: "Aorist unregelmäßig: gelir (nicht „geler“)." },
  { id: "tr-a1.w253", t: "yapmak", pos: "v", n: "machen; tun", ex: "Ne yapıyorsun?", exn: "Was machst du gerade?", topic: "verbs" },
  { id: "tr-a1.w254", t: "etmek", pos: "v", n: "machen (in festen Verbindungen)", ex: "Bana yardım eder misin?", exn: "Hilfst du mir?", topic: "verbs", note: "Fast nur mit einem Nomen davor: yardım etmek (helfen), teşekkür etmek (danken). Vor Vokal wird t zu d: ediyorum." },
  { id: "tr-a1.w255", t: "yemek", pos: "v", n: "essen; das Essen", ex: "Akşam ne yiyoruz?", exn: "Was essen wir heute Abend?", topic: "verbs", note: "Unregelmäßig: yiyorum (ich esse) – nicht verwechseln mit yemiyorum (ich esse nicht). Als Nomen: das Essen." },
  { id: "tr-a1.w256", t: "içmek", pos: "v", n: "trinken", ex: "Akşamları bitki çayı içiyorum.", exn: "Abends trinke ich Kräutertee.", topic: "verbs", note: "Auch für Rauchen: sigara içmek (wörtlich „Zigarette trinken“)." },
  { id: "tr-a1.w257", t: "uyumak", pos: "v", n: "schlafen", ex: "Dün gece iyi uyudum.", exn: "Letzte Nacht habe ich gut geschlafen.", topic: "verbs" },
  { id: "tr-a1.w258", t: "kalkmak", pos: "v", n: "aufstehen; abfahren", ex: "Kaçta kalkıyorsun?", exn: "Wann stehst du auf?", topic: "verbs", note: "Bei Zügen und Bussen: abfahren – Tren kalkıyor." },
  { id: "tr-a1.w259", t: "oturmak", pos: "v", n: "sitzen; sich setzen; wohnen", ex: "Lütfen oturun.", exn: "Setzen Sie sich bitte.", topic: "verbs", note: "Heißt auch „wohnen“: Nerede oturuyorsun? = Wo wohnst du?" },
  { id: "tr-a1.w260", t: "yaşamak", pos: "v", n: "leben; wohnen", ex: "Kaç yıldır Almanya'da yaşıyorsun?", exn: "Seit wie vielen Jahren lebst du in Deutschland?", topic: "verbs" },
  { id: "tr-a1.w261", t: "çalışmak", pos: "v", n: "arbeiten; lernen (für etwas)", ex: "Bu akşam sınav için çalışıyorum.", exn: "Heute Abend lerne ich für die Prüfung.", topic: "verbs", note: "Bedeutet auch „lernen, üben“ und bei Geräten „funktionieren“: Telefon çalışmıyor." },
  { id: "tr-a1.w262", t: "öğrenmek", pos: "v", n: "lernen; erfahren", ex: "Her gün beş yeni kelime öğreniyorum.", exn: "Ich lerne jeden Tag fünf neue Wörter.", topic: "verbs" },
  { id: "tr-a1.w263", t: "okumak", pos: "v", n: "lesen; studieren", ex: "Akşamları kitap okuyorum.", exn: "Abends lese ich.", topic: "verbs", note: "Auch „studieren“: Tıp okuyorum = Ich studiere Medizin." },
  { id: "tr-a1.w264", t: "yazmak", pos: "v", n: "schreiben", ex: "Adınızı buraya yazın.", exn: "Schreiben Sie Ihren Namen hierhin.", topic: "verbs" },
  { id: "tr-a1.w265", t: "konuşmak", pos: "v", n: "sprechen; reden", ex: "Biraz yavaş konuşur musunuz?", exn: "Könnten Sie bitte etwas langsamer sprechen?", topic: "verbs" },
  { id: "tr-a1.w266", t: "söylemek", pos: "v", n: "sagen", ex: "Ona ne söyledin?", exn: "Was hast du ihm gesagt?", topic: "verbs" },
  { id: "tr-a1.w267", t: "anlamak", pos: "v", n: "verstehen", ex: "Anlamadım, tekrar eder misiniz?", exn: "Das habe ich nicht verstanden, können Sie es wiederholen?", topic: "verbs", note: "Wer etwas nicht versteht, sagt meist die Vergangenheit: Anlamadım (wörtlich: „Ich habe nicht verstanden“)." },
  { id: "tr-a1.w268", t: "bilmek", pos: "v", n: "wissen; kennen; können (Sprache)", ex: "Onun adresini bilmiyorum.", exn: "Ich kenne seine Adresse nicht.", topic: "verbs", note: "Aorist unregelmäßig: bilir (nicht „biler“)." },
  { id: "tr-a1.w269", t: "istemek", pos: "v", n: "wollen; möchten", ex: "Bir bardak çay istiyorum.", exn: "Ich möchte ein Glas Tee.", topic: "verbs" },
  { id: "tr-a1.w270", t: "sevmek", pos: "v", n: "lieben; mögen", ex: "Seni seviyorum.", exn: "Ich liebe dich.", topic: "verbs", note: "Das Geliebte steht im Akkusativ: seni (dich), çayı (den Tee)." },
  { id: "tr-a1.w271", t: "almak", pos: "v", n: "nehmen; kaufen; bekommen", ex: "Pazardan meyve alıyorum.", exn: "Ich kaufe auf dem Markt Obst.", topic: "verbs", note: "Aorist unregelmäßig: alır (nicht „alar“)." },
  { id: "tr-a1.w272", t: "vermek", pos: "v", n: "geben", ex: "Annem bana harçlık veriyor.", exn: "Meine Mutter gibt mir Taschengeld.", topic: "verbs", note: "Aorist unregelmäßig: verir (nicht „verer“)." },
  { id: "tr-a1.w273", t: "satmak", pos: "v", n: "verkaufen", ex: "Komşum arabasını satıyor.", exn: "Mein Nachbar verkauft sein Auto.", topic: "verbs" },
  { id: "tr-a1.w274", t: "ödemek", pos: "v", n: "bezahlen", ex: "Bugün ben ödüyorum.", exn: "Heute zahle ich.", topic: "verbs", note: "Vor -iyor fällt das e weg und die Endung passt sich an: ödüyorum (nicht „ödeyorum“)." },
  { id: "tr-a1.w275", t: "açmak", pos: "v", n: "öffnen; einschalten", ex: "Kapıyı açar mısın?", exn: "Machst du die Tür auf?", topic: "verbs", note: "Auch für Geräte: ışığı açmak (das Licht anmachen)." },
  { id: "tr-a1.w276", t: "kapatmak", pos: "v", n: "schließen; ausschalten", ex: "Telefonunu kapat, lütfen.", exn: "Schalte bitte dein Handy aus.", topic: "verbs" },
  { id: "tr-a1.w277", t: "beklemek", pos: "v", n: "warten; erwarten", ex: "Seni durakta bekliyorum.", exn: "Ich warte an der Haltestelle auf dich.", topic: "verbs", note: "Ohne „auf“: Die Person steht im Akkusativ – seni bekliyorum (ich warte auf dich)." },
  { id: "tr-a1.w278", t: "bakmak", pos: "v", n: "schauen; sich kümmern um", ex: "Şuna bak!", exn: "Schau dir das an!", topic: "verbs", note: "Mit Dativ: bana bak (schau mich an), çocuğa bakmak (auf das Kind aufpassen)." },
  { id: "tr-a1.w279", t: "görmek", pos: "v", n: "sehen", ex: "Seni görmek çok güzel.", exn: "Schön, dich zu sehen.", topic: "verbs", note: "Aorist unregelmäßig: görür. Gezielt hinschauen heißt bakmak." },
  { id: "tr-a1.w280", t: "duymak", pos: "v", n: "hören", ex: "Beni duyuyor musun?", exn: "Hörst du mich?", topic: "verbs", note: "duymak = (zufällig) hören. Bewusst zuhören = dinlemek." },
  { id: "tr-a1.w281", t: "dinlemek", pos: "v", n: "zuhören; (Musik) hören", ex: "Lütfen beni dinle.", exn: "Hör mir bitte zu.", topic: "verbs" },
  { id: "tr-a1.w282", t: "izlemek", pos: "v", n: "ansehen; anschauen (Film, Spiel)", ex: "Hangi filmi izliyoruz?", exn: "Welchen Film schauen wir?", topic: "verbs", note: "Gleichbedeutend: seyretmek." },
  { id: "tr-a1.w283", t: "binmek", pos: "v", n: "einsteigen; (mit etwas) fahren", ex: "Otobüse nerede biniyoruz?", exn: "Wo steigen wir in den Bus ein?", topic: "verbs", note: "Mit Dativ: otobüse binmek. Auch: ata binmek (reiten)." },
  { id: "tr-a1.w284", t: "inmek", pos: "v", n: "aussteigen; hinuntergehen", ex: "Bir sonraki durakta iniyorum.", exn: "Ich steige an der nächsten Haltestelle aus.", topic: "verbs", note: "Woraus man aussteigt, steht im Ablativ: otobüsten inmek." },
  { id: "tr-a1.w285", t: "dönmek", pos: "v", n: "zurückkehren; abbiegen; sich drehen", ex: "Saat kaçta eve dönüyorsun?", exn: "Wann kommst du nach Hause zurück?", topic: "verbs" },
  { id: "tr-a1.w286", t: "başlamak", pos: "v", n: "anfangen; beginnen", ex: "Film başlıyor, sessiz olun!", exn: "Der Film fängt an, seid leise!", topic: "verbs", note: "Womit man anfängt, steht im Dativ: işe başlamak (mit der Arbeit anfangen)." },
  { id: "tr-a1.w287", t: "bitmek", pos: "v", n: "zu Ende gehen; alle sein", ex: "Süt bitti.", exn: "Die Milch ist alle.", topic: "verbs" },
  { id: "tr-a1.w288", t: "sormak", pos: "v", n: "fragen", ex: "Öğretmene sorabilirsin.", exn: "Du kannst die Lehrerin fragen.", topic: "verbs", note: "Die gefragte Person steht im Dativ: öğretmene sormak (nicht „öğretmeni“)." },
  { id: "tr-a1.w289", t: "aramak", pos: "v", n: "suchen; anrufen", ex: "Akşam seni ararım.", exn: "Ich rufe dich heute Abend an.", topic: "verbs", note: "Zwei Bedeutungen: suchen und anrufen. Der Zusammenhang entscheidet." },
  { id: "tr-a1.w290", t: "bulmak", pos: "v", n: "finden", ex: "Yeni bir ev bulduk.", exn: "Wir haben eine neue Wohnung gefunden.", topic: "verbs", note: "Aorist unregelmäßig: bulur." },

  /* ---------- Eigenschaften (adj) ---------- */
  { id: "tr-a1.w291", t: "büyük", pos: "adj", n: "groß; älter", ex: "Kızımın büyük bir köpeği var.", exn: "Meine Tochter hat einen großen Hund.", topic: "adj", note: "Bei Personen auch „älter“: büyük kardeş (älterer Bruder / ältere Schwester). Große Menschen: uzun boylu." },
  { id: "tr-a1.w292", t: "küçük", pos: "adj", n: "klein; jünger", ex: "Küçük bir evde oturuyoruz.", exn: "Wir wohnen in einem kleinen Haus.", topic: "adj" },
  { id: "tr-a1.w293", t: "yeni", pos: "adj", n: "neu", ex: "Yeni telefonun çok güzel.", exn: "Dein neues Handy ist sehr schön.", topic: "adj" },
  { id: "tr-a1.w294", t: "eski", pos: "adj", n: "alt (bei Dingen); ehemalig", ex: "Bu bina çok eski.", exn: "Dieses Gebäude ist sehr alt.", topic: "adj", note: "eski nur für Dinge! Bei Menschen sagt man yaşlı. eski adresim = meine frühere Adresse." },
  { id: "tr-a1.w295", t: "genç", pos: "adj", n: "jung", ex: "Annem çok genç görünüyor.", exn: "Meine Mutter sieht sehr jung aus.", topic: "adj" },
  { id: "tr-a1.w296", t: "yaşlı", pos: "adj", n: "alt (bei Menschen, Tieren, Bäumen)", ex: "Yaşlı bir kadın otobüse biniyor.", exn: "Eine alte Frau steigt in den Bus.", topic: "adj", note: "Für Dinge sagt man eski." },
  { id: "tr-a1.w297", t: "güzel", pos: "adj", n: "schön; gut; lecker", ex: "Ne güzel bir gün!", exn: "Was für ein schöner Tag!", topic: "adj", note: "Sehr vielseitig: auch für Essen (lecker) und Pläne (gut): Güzel fikir!" },
  { id: "tr-a1.w298", t: "iyi", pos: "adj", n: "gut", ex: "Bu iyi bir fikir.", exn: "Das ist eine gute Idee.", topic: "adj" },
  { id: "tr-a1.w299", t: "kötü", pos: "adj", n: "schlecht; schlimm", ex: "Bugün hava çok kötü.", exn: "Heute ist das Wetter sehr schlecht.", topic: "adj" },
  { id: "tr-a1.w300", t: "uzun", pos: "adj", n: "lang; groß (Person)", ex: "Kardeşim çok uzun boylu.", exn: "Mein Bruder ist sehr groß.", topic: "adj", note: "Körpergröße: uzun boylu (groß), kısa boylu (klein) – nicht büyük/küçük." },
  { id: "tr-a1.w301", t: "kısa", pos: "adj", n: "kurz; klein (Person)", ex: "Saçlarım artık kısa.", exn: "Meine Haare sind jetzt kurz.", topic: "adj" },
  { id: "tr-a1.w302", t: "hızlı", pos: "adj", n: "schnell", ex: "Bu tren çok hızlı.", exn: "Dieser Zug ist sehr schnell.", topic: "adj" },
  { id: "tr-a1.w303", t: "yavaş", pos: "adj", n: "langsam", ex: "Yavaş yavaş öğreniyorum.", exn: "Ich lerne Schritt für Schritt.", topic: "adj", note: "yavaş yavaş = nach und nach, ganz langsam." },
  { id: "tr-a1.w304", t: "kolay", pos: "adj", n: "leicht; einfach", ex: "Türkçe zor değil, çok kolay!", exn: "Türkisch ist nicht schwer, es ist ganz leicht!", topic: "adj" },
  { id: "tr-a1.w305", t: "zor", pos: "adj", n: "schwer; schwierig", ex: "Bu soru çok zor.", exn: "Diese Frage ist sehr schwer.", topic: "adj", note: "Nur „schwierig“! Schwer im Gewicht heißt ağır." },
  { id: "tr-a1.w306", t: "açık", pos: "adj", n: "offen; geöffnet; hell (Farbe)", ex: "Eczane pazar günü açık mı?", exn: "Hat die Apotheke am Sonntag offen?", topic: "adj", note: "Bei Farben: açık mavi (hellblau), koyu mavi (dunkelblau)." },
  { id: "tr-a1.w307", t: "kapalı", pos: "adj", n: "geschlossen; bewölkt", ex: "Müze pazartesi günleri kapalı.", exn: "Das Museum ist montags geschlossen.", topic: "adj", note: "Beim Wetter: Hava kapalı = Es ist bewölkt." },
  { id: "tr-a1.w308", t: "dolu", pos: "adj", n: "voll; besetzt", ex: "Otobüs çok dolu.", exn: "Der Bus ist sehr voll.", topic: "adj" },
  { id: "tr-a1.w309", t: "boş", pos: "adj", n: "leer; frei", ex: "Bu sandalye boş mu?", exn: "Ist dieser Stuhl frei?", topic: "adj", note: "Bei Personen: Boş musun? = Hast du Zeit?" },
  { id: "tr-a1.w310", t: "temiz", pos: "adj", n: "sauber", ex: "Oteldeki odalar çok temiz.", exn: "Die Zimmer im Hotel sind sehr sauber.", topic: "adj" },
  { id: "tr-a1.w311", t: "mutlu", pos: "adj", n: "glücklich", ex: "Bugün çok mutluyum.", exn: "Heute bin ich sehr glücklich.", topic: "adj" },
  { id: "tr-a1.w312", t: "üzgün", pos: "adj", n: "traurig", ex: "Neden üzgünsün?", exn: "Warum bist du traurig?", topic: "adj" },
  { id: "tr-a1.w313", t: "kırmızı", pos: "adj", n: "rot", ex: "Kırmızı elbiseyi beğendim.", exn: "Mir gefällt das rote Kleid.", topic: "adj" },
  { id: "tr-a1.w314", t: "mavi", pos: "adj", n: "blau", ex: "Gökyüzü bugün masmavi.", exn: "Der Himmel ist heute strahlend blau.", topic: "adj", note: "masmavi = ganz blau (verstärkte Form, wie kıpkırmızı, bembeyaz)." },
  { id: "tr-a1.w315", t: "yeşil", pos: "adj", n: "grün", ex: "Yeşil çay sever misin?", exn: "Magst du grünen Tee?", topic: "adj" },
  { id: "tr-a1.w316", t: "sarı", pos: "adj", n: "gelb", ex: "Sarı ceketli adam benim babam.", exn: "Der Mann mit der gelben Jacke ist mein Vater.", topic: "adj" },
  { id: "tr-a1.w317", t: "siyah", pos: "adj", n: "schwarz", ex: "Siyah çantam nerede?", exn: "Wo ist meine schwarze Tasche?", topic: "adj", note: "Auch kara – vor allem in festen Ausdrücken: Karadeniz (das Schwarze Meer)." },
  { id: "tr-a1.w318", t: "beyaz", pos: "adj", n: "weiß", ex: "Beyaz gömlek sana çok yakışıyor.", exn: "Das weiße Hemd steht dir sehr gut.", topic: "adj" },

  /* ---------- Kleine Wörter (small) ---------- */
  { id: "tr-a1.w319", t: "ben", pos: "x", n: "ich", ex: "Ben öğrenciyim, ya sen?", exn: "Ich bin Student, und du?", topic: "small", note: "Das Pronomen fällt oft weg, weil die Endung die Person schon zeigt: Öğrenciyim = Ich bin Student." },
  { id: "tr-a1.w320", t: "sen", pos: "x", n: "du", ex: "Sen nerede oturuyorsun?", exn: "Wo wohnst du?", topic: "small", note: "Wie im Deutschen nur für Freunde, Familie und Kinder. Höflich: siz." },
  { id: "tr-a1.w321", t: "o", pos: "x", n: "er; sie; es; jener", ex: "O benim kız kardeşim.", exn: "Sie ist meine Schwester.", topic: "small", note: "Es gibt kein grammatisches Geschlecht: o = er, sie und es." },
  { id: "tr-a1.w322", t: "biz", pos: "x", n: "wir", ex: "Biz Berlin'de oturuyoruz.", exn: "Wir wohnen in Berlin.", topic: "small" },
  { id: "tr-a1.w323", t: "siz", pos: "x", n: "ihr; Sie (höflich)", ex: "Siz nerelisiniz?", exn: "Woher kommen Sie?", topic: "small", note: "siz ist sowohl „ihr“ als auch das höfliche „Sie“." },
  { id: "tr-a1.w324", t: "onlar", pos: "x", n: "sie (Plural)", ex: "Onlar bugün gelmiyor.", exn: "Sie kommen heute nicht.", topic: "small" },
  { id: "tr-a1.w325", t: "bu", pos: "x", n: "dies; das (hier)", ex: "Bu kimin çantası?", exn: "Wessen Tasche ist das?", topic: "small", note: "bu = hier bei mir, şu = da (oft mit Zeigen), o = dort." },
  { id: "tr-a1.w326", t: "şu", pos: "x", n: "das da; jenes", ex: "Şu çantayı görebilir miyim?", exn: "Kann ich mir die Tasche da ansehen?", topic: "small" },
  { id: "tr-a1.w327", t: "ne", pos: "x", n: "was", ex: "Bu ne?", exn: "Was ist das?", topic: "small" },
  { id: "tr-a1.w328", t: "kim", pos: "x", n: "wer", ex: "Kapıdaki kim?", exn: "Wer ist an der Tür?", topic: "small" },
  { id: "tr-a1.w329", t: "nerede", pos: "x", n: "wo", ex: "Tuvalet nerede?", exn: "Wo ist die Toilette?", topic: "small", note: "nereye = wohin, nereden = woher." },
  { id: "tr-a1.w330", t: "nasıl", pos: "x", n: "wie", ex: "Bu kelime nasıl yazılıyor?", exn: "Wie schreibt man dieses Wort?", topic: "small" },
  { id: "tr-a1.w331", t: "ne zaman", pos: "x", n: "wann", ex: "Tren ne zaman geliyor?", exn: "Wann kommt der Zug?", topic: "small", note: "Getrennt geschrieben. Für Uhrzeiten auch: Saat kaçta? (Um wie viel Uhr?)" },
  { id: "tr-a1.w332", t: "neden", pos: "x", n: "warum", ex: "Neden gülüyorsun?", exn: "Warum lachst du?", topic: "small", note: "Gleichbedeutend: niye, niçin." },
  { id: "tr-a1.w333", t: "kaç", pos: "x", n: "wie viel(e)", ex: "Kaç kardeşin var?", exn: "Wie viele Geschwister hast du?", topic: "small", note: "Nach kaç steht der Singular: kaç kardeş (nicht „kaç kardeşler“)." },
  { id: "tr-a1.w334", t: "hangi", pos: "x", n: "welche(r, s)", ex: "Hangi otobüs merkeze gidiyor?", exn: "Welcher Bus fährt ins Zentrum?", topic: "small" },
  { id: "tr-a1.w335", t: "evet", pos: "x", n: "ja", ex: "Evet, haklısın.", exn: "Ja, du hast recht.", topic: "small" },
  { id: "tr-a1.w336", t: "hayır", pos: "x", n: "nein", ex: "Hayır, teşekkürler.", exn: "Nein, danke.", topic: "small", note: "Im Alltag hört man oft „yok“ statt hayır. Achtung Körpersprache: Kopf nach oben + Zungenschnalzen heißt „nein“." },
  { id: "tr-a1.w337", t: "var", pos: "x", n: "es gibt; vorhanden", ex: "Burada bir eczane var mı?", exn: "Gibt es hier eine Apotheke?", topic: "small", note: "„haben“ drückt man mit var aus: Arabam var = Ich habe ein Auto (wörtlich: Mein Auto ist vorhanden)." },
  { id: "tr-a1.w338", t: "yok", pos: "x", n: "es gibt nicht; nicht vorhanden", ex: "Maalesef bugün balık yok.", exn: "Leider gibt es heute keinen Fisch.", topic: "small", note: "„nicht haben“: Arabam yok = Ich habe kein Auto." },
  { id: "tr-a1.w339", t: "ve", pos: "x", n: "und", ex: "Ekmek ve peynir aldım.", exn: "Ich habe Brot und Käse gekauft.", topic: "small" },
  { id: "tr-a1.w340", t: "ama", pos: "x", n: "aber", ex: "Yorgunum ama mutluyum.", exn: "Ich bin müde, aber glücklich.", topic: "small" },
  { id: "tr-a1.w341", t: "çok", pos: "x", n: "sehr; viel", ex: "Çok teşekkürler!", exn: "Vielen Dank!", topic: "small", note: "Nach çok steht der Singular: çok kitap (viele Bücher)." },
  { id: "tr-a1.w342", t: "biraz", pos: "x", n: "ein bisschen; etwas", ex: "Biraz daha çay ister misin?", exn: "Möchtest du noch etwas Tee?", topic: "small", note: "Zusammengeschrieben: bir + az = biraz." },
  { id: "tr-a1.w343", t: "şimdi", pos: "adv", n: "jetzt", ex: "Şimdi müsait değilim.", exn: "Ich habe gerade keine Zeit.", topic: "small" },
  { id: "tr-a1.w344", t: "burada", pos: "adv", n: "hier", ex: "Burada sigara içmek yasak.", exn: "Rauchen ist hier verboten.", topic: "small", note: "burada = hier, şurada = da, orada = dort." },
  { id: "tr-a1.w345", t: "sonra", pos: "adv", n: "später; danach; nach", ex: "Sonra konuşalım.", exn: "Lass uns später reden.", topic: "small", note: "„nach“ mit Ablativ: dersten sonra (nach dem Unterricht)." },
  { id: "tr-a1.w346", t: "tamam", pos: "x", n: "okay; in Ordnung", ex: "Tamam, anladım.", exn: "Okay, verstanden.", topic: "small" },
  { id: "tr-a1.w347", t: "değil", pos: "x", n: "nicht (bei Nomen und Adjektiven)", ex: "Bu benim çantam değil.", exn: "Das ist nicht meine Tasche.", topic: "small", note: "değil verneint Nomen und Adjektive. Verben werden mit -me/-ma verneint: gelmiyorum." },
  { id: "tr-a1.w348", t: "için", pos: "x", n: "für; um … zu", ex: "Bu hediye senin için.", exn: "Dieses Geschenk ist für dich.", topic: "small", note: "Pronomen stehen davor im Genitiv: benim için, senin için. Achtung: için! heißt auch „Trinken Sie!“ (von içmek)." },
  { id: "tr-a1.w349", t: "ile", pos: "x", n: "mit; und", ex: "Kahvemi sütle içiyorum.", exn: "Ich trinke meinen Kaffee mit Milch.", topic: "small", note: "Meist als Endung angehängt: sütle, otobüsle; nach Vokal mit y: arabayla." },
  { id: "tr-a1.w350", t: "de / da", pos: "x", n: "auch", ex: "Ben de geliyorum.", exn: "Ich komme auch.", topic: "small", note: "Wird **getrennt** geschrieben und richtet sich nach der Vokalharmonie: ben de, biz de, o da. Nicht verwechseln mit der Endung -de (in): evde." }
]);
})(window.KOPRU);
